def solve(n):
    primes = [2, 3, 5, 7, 11, 13, 17, 19]
    distinct_primes = []
    temp = n
    for p in primes:
        if temp % p == 0:
            distinct_primes.append(p)
            while temp % p == 0:
                temp //= p
    k = len(distinct_primes)
    return (1 << k) - 1

def solve(n, nums):
    total = 0
    for x in nums:
        val = pow(2, x, 100) if x >= 2 else (2 if x == 1 else 1)
        total = (total + val) % 100
    return total

def solve(n, grid):
    hurdles = {'S', 'L', 'W', 'T'}
    # Collect steps along route
    results = []
    for r in range(n):
        for c in range(n):
            if grid[r][c] == 'R':
                surrounding = []
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0: continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] in hurdles:
                            surrounding.append(grid[nr][nc])
                if surrounding:
                    results.append(' '.join(sorted(surrounding)))
                else:
                    results.append('NO HURDLES')
    results.append('DESTINATION')
    return results
